import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Закон об Охране Окружающей Среды","description":"","frontmatter":{},"headers":[],"relativePath":"ru/46-环境保护法.md","filePath":"ru/46-环境保护法.md","lastUpdated":1789183869000}'),e={name:"ru/46-环境保护法.md"};function d(o,t,h,n,s,b){return i(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="закон-об-охране-окружающеи-среды" tabindex="-1">Закон об Охране Окружающей Среды <a class="header-anchor" href="#закон-об-охране-окружающеи-среды" aria-label="Permalink to &quot;Закон об Охране Окружающей Среды&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>46</td></tr><tr><td>Модуль</td><td>Правовая система и структура управления</td></tr><tr><td>Ключевые слова</td><td>Охрана окружающей среды, Первооснова Вселенной, Экологический симбиоз, Устойчивое развитие, Предотвращение загрязнений</td></tr></tbody></table><h2 id="i-цель-законодательства-и-основные-принципы" tabindex="-1">I. Цель законодательства и основные принципы <a class="header-anchor" href="#i-цель-законодательства-и-основные-принципы" aria-label="Permalink to &quot;I. Цель законодательства и основные принципы&quot;">​</a></h2><p><em>Закон об Охране Окружающей Среды</em> — один из пяти вспомогательных законов Симбиотической Цивилизации Якоря. Он направлен на защиту экологической среды и Первоосновы Вселенной внутри Вселенной Хэнъюань, утверждение философии управления окружающей средой «симбиотическая эволюция, устойчивое развитие», предотвращение разрушения космической экосистемы хищническим освоением и охрану основы выживания для совместного продвижения Десяти Тысяч Рас.</p><p>Настоящий Закон устанавливает следующие основные принципы:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Содержание</th></tr></thead><tbody><tr><td>Защита Первоосновы</td><td>Первооснова Вселенной — основа всякой жизни и эволюции; она должна защищаться в приоритетном порядке; разрушительная добыча запрещена</td></tr><tr><td>Экологический симбиоз</td><td>Человек и природа, все расы и экосистемы находятся в симбиотических отношениях; разрушение экологии — разрушение собственной основы выживания</td></tr><tr><td>Устойчивость</td><td>Всякая деятельность по освоению должна учитывать интересы нынешнего и будущих поколений; против хищнического истощения</td></tr><tr><td>Профилактика прежде всего</td><td>Охрана окружающей среды ориентирована на профилактику; создаётся институт оценки воздействия на окружающую среду для предотвращения загрязнений</td></tr><tr><td>Ответственность загрязнителя</td><td>Субъекты, причинившие загрязнение окружающей среды и разрушение экологии, обязаны нести ответственность за ликвидацию и возмещение</td></tr><tr><td>Участие общественности</td><td>Поощряется участие общественности в охране окружающей среды; гарантируются права общественности на информацию и участие</td></tr><tr><td>Межплоскостная координация</td><td>Охрана окружающей среды продвигается скоординированно между плоскостями; создаётся механизм сотрудничества в межплоскостном экологическом управлении</td></tr></tbody></table><h2 id="ii-сфера-охраны-окружающеи-среды" tabindex="-1">II. Сфера охраны окружающей среды <a class="header-anchor" href="#ii-сфера-охраны-окружающеи-среды" aria-label="Permalink to &quot;II. Сфера охраны окружающей среды&quot;">​</a></h2><p>Охраняемая настоящим Законом среда включает все экосистемы и элементы окружающей среды внутри Вселенной Хэнъюань:</p><ol><li><strong>Атмосферная среда</strong>: включая концентрацию энергии и баланс состава атмосферы и энергетических слоёв каждой планеты.</li><li><strong>Водная среда</strong>: включая качество и количество поверхностных вод, подземных вод, океанов и энергетических вод между плоскостями.</li><li><strong>Почвенная среда</strong>: включая качество почвы и плодородие сухопутных почв и рудных жил культивационных ресурсов.</li><li><strong>Биологическое разнообразие</strong>: включая охрану видов и мест обитания всех растений, животных, микроорганизмов и необычных существ.</li><li><strong>Энергетическая среда</strong>: включая концентрацию и баланс распределения духовной энергии неба и земли, первоначальной энергии и фрагментов законов.</li><li><strong>Пространственная среда</strong>: включая пространственную стабильность плоскостей, пространственные трещины и экологическую безопасность свёрнутого пространства.</li><li><strong>Среда области сознания</strong>: включая информационную чистоту пространства коллективного сознания и предотвращение духовных загрязнений.</li></ol><h2 id="iii-основные-институты" tabindex="-1">III. Основные институты <a class="header-anchor" href="#iii-основные-институты" aria-label="Permalink to &quot;III. Основные институты&quot;">​</a></h2><h3 id="i-институт-оценки-воздеиствия-на-окружающую-среду" tabindex="-1">(I) Институт оценки воздействия на окружающую среду <a class="header-anchor" href="#i-институт-оценки-воздеиствия-на-окружающую-среду" aria-label="Permalink to &quot;(I) Институт оценки воздействия на окружающую среду&quot;">​</a></h3><p>Все проекты освоения и строительства, способные оказать значительное воздействие на окружающую среду, обязаны пройти оценку воздействия на окружающую среду до начала работ. Содержание оценки включает: воздействие проекта на атмосферные, водные, почвенные, биологические, энергетические, пространственные и другие элементы среды, меры предотвращения и смягчения, оценку экологических рисков и т.д. Проекты, не прошедшие оценку воздействия на окружающую среду, не могут начинать строительство.</p><h3 id="ii-институт-разрешении-на-выбросы-и-контроля-общего-объема" tabindex="-1">(II) Институт разрешений на выбросы и контроля общего объёма <a class="header-anchor" href="#ii-институт-разрешении-на-выбросы-и-контроля-общего-объема" aria-label="Permalink to &quot;(II) Институт разрешений на выбросы и контроля общего объёма&quot;">​</a></h3><p>Государство вводит разрешительное управление и контроль общего объёма выбросов загрязняющих веществ. Единицы выбросов обязаны получать разрешения на выбросы загрязняющих веществ и выбрасывать загрязняющие вещества в соответствии с видами, концентрациями и общими объёмами, указанными в разрешениях. Государство определяет общий объём выбросов загрязняющих веществ для каждого региона и каждой плоскости с учётом экологической ёмкости, поэтапно раскладывая и реализуя его.</p><h3 id="iii-институт-красных-линии-экологическои-защиты" tabindex="-1">(III) Институт красных линий экологической защиты <a class="header-anchor" href="#iii-институт-красных-линии-экологическои-защиты" aria-label="Permalink to &quot;(III) Институт красных линий экологической защиты&quot;">​</a></h3><p>Государство обозначает красные линии экологической защиты в районах особой экологической ценности, включая:</p><table tabindex="0"><thead><tr><th>Тип красной линии</th><th>Охраняемое содержание</th></tr></thead><tbody><tr><td>Зона защиты Первоосновы</td><td>Ключевые районы производства энергии Первоосновы Вселенной; всякая деятельность по освоению запрещена</td></tr><tr><td>Место обитания видов</td><td>Ключевые места обитания редких и находящихся под угрозой видов; разрушение и вмешательство запрещены</td></tr><tr><td>Зона экологического барьера</td><td>Ключевые экосистемы, поддерживающие региональный экологический баланс; освоение ограничено</td></tr><tr><td>Священные места культивации</td><td>Энергонасыщенные районы особой культивационной ценности; применяется охранительное использование</td></tr><tr><td>Пограничная полоса плоскостей</td><td>Экологические переходные зоны между плоскостями; пространственно-разрушительное освоение запрещено</td></tr></tbody></table><h3 id="iv-институт-экологического-мониторинга-и-предупреждения" tabindex="-1">(IV) Институт экологического мониторинга и предупреждения <a class="header-anchor" href="#iv-институт-экологического-мониторинга-и-предупреждения" aria-label="Permalink to &quot;(IV) Институт экологического мониторинга и предупреждения&quot;">​</a></h3><p>Государство создаёт сеть экологического мониторинга, охватывающую всю вселенную, в реальном времени отслеживая изменения элементов окружающей среды. Для возможных крупных событий загрязнения окружающей среды и разрушения экологии создаётся механизм предупреждения, своевременно публикующий предупреждения и запускающий экстренное реагирование.</p><h3 id="v-институт-экологическои-компенсации" tabindex="-1">(V) Институт экологической компенсации <a class="header-anchor" href="#v-институт-экологическои-компенсации" aria-label="Permalink to &quot;(V) Институт экологической компенсации&quot;">​</a></h3><p>Районы и группы, чьё освоение ограничено из-за охраны окружающей среды, имеют право на экологическую компенсацию. Средства экологической компенсации выделяются из общественного фонда накопления и доходов от освоения ресурсов, используются для экономического развития компенсируемых районов и улучшения жизни жителей.</p><h2 id="iv-экологическое-регулирование-культивационнои-деятельности" tabindex="-1">IV. Экологическое регулирование культивационной деятельности <a class="header-anchor" href="#iv-экологическое-регулирование-культивационнои-деятельности" aria-label="Permalink to &quot;IV. Экологическое регулирование культивационной деятельности&quot;">​</a></h2><p>Воздействие культивационной деятельности на окружающую среду — особая сфера охраны окружающей среды во Вселенной Хэнъюань; настоящий Закон устанавливает специальные регулятивные положения:</p><ol><li><strong>Регулирование добычи энергии</strong>: добыча культивационных ресурсов должна соответствовать принципу устойчивости; разрушительная добыча, ведущая к истощению энергии, запрещена. Объём добычи не должен превышать естественную скорость восстановления региональной энергии.</li><li><strong>Обработка культивационных отходов</strong>: энергетические остатки, выброшенные пилюли, повреждённые артефакты и другие отходы, образующиеся при культивации, должны обрабатываться в соответствии с правилами; случайное выбрасывание, вызывающее энергетическое загрязнение, запрещено.</li><li><strong>Экологическая оценка продвинутой культивации</strong>: прорывы и затворничество продвинутых культиваторов могут оказывать значительное воздействие на окружающую среду; необходимо заранее проводить экологическую оценку и принимать защитные меры.</li><li><strong>Разрешение на освоение плоскостей</strong>: освоение новых плоскостей должно проходить экологическую оценку и экологическое обследование; освоение возможно только после разработки плана экологической защиты.</li><li><strong>Защита мест обитания необычных существ</strong>: места обитания необычных существ включаются в красные линии экологической защиты; исследование и освоение без разрешения запрещены.</li></ol><h2 id="v-юридическая-ответственность" tabindex="-1">V. Юридическая ответственность <a class="header-anchor" href="#v-юридическая-ответственность" aria-label="Permalink to &quot;V. Юридическая ответственность&quot;">​</a></h2><p>Действия, нарушающие положения настоящего Закона, в зависимости от тяжести обстоятельств несут следующую ответственность:</p><ul><li>Начало строительства без прохождения оценки воздействия на окружающую среду — предписание остановить строительство, восстановить первоначальное состояние и штраф.</li><li>Сверхнормативные выбросы загрязняющих веществ — предписание устранить в срок и штраф; при серьёзных обстоятельствах — предписание приостановить деятельность и закрыться.</li><li>Разрушение красных линий экологической защиты — предписание восстановить первоначальное состояние и штраф; при серьёзных обстоятельствах — уголовная ответственность.</li><li>Разрушительная добыча культивационных ресурсов — конфискация незаконного дохода и штраф; аннулирование разрешения на добычу.</li><li>Причинение крупных аварий загрязнения окружающей среды — ответственность за возмещение; при наличии состава преступления — уголовная ответственность.</li><li>Халатность или злоупотребление полномочиями инспекторами по охране окружающей среды — взыскание; при наличии состава преступления — уголовная ответственность.</li></ul><h2 id="vi-участие-общественности-и-экологическии-публичныи-иск" tabindex="-1">VI. Участие общественности и экологический публичный иск <a class="header-anchor" href="#vi-участие-общественности-и-экологическии-публичныи-иск" aria-label="Permalink to &quot;VI. Участие общественности и экологический публичный иск&quot;">​</a></h2><p>Общественность имеет право участвовать в охране окружающей среды, конкретные каналы включают:</p><ol><li>Представление мнений и предложений по проектам оценки воздействия на окружающую среду.</li><li>Сообщение и жалобы на действия по загрязнению окружающей среды и разрушению экологии.</li><li>Создание природоохранных организаций в соответствии с законом, участие в экологическом надзоре и общественно полезной деятельности.</li><li>За действия, загрязняющие окружающую среду, разрушающие экологию и наносящие вред общественным интересам, природоохранные организации могут подавать экологический публичный иск в Симбиотический Суд.</li></ol><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p><em>Закон об Охране Окружающей Среды</em> — правовая гарантия философии устойчивого развития Симбиотической Цивилизации Якоря. Создавая такие институты, как оценка воздействия на окружающую среду, красные линии экологической защиты и контроль общего объёма, он включает охрану окружающей среды во всю деятельность по освоению и культивации, обеспечивая устойчивость Первоосновы Вселенной и экосистемы, охраняя вечную основу выживания для совместного продвижения Десяти Тысяч Рас.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Симбиотическая Конституция: Общие Принципы)</li><li>39-住房与环境保障 (Жильё и защита окружающей среды)</li><li>15-能量循环与转化法则 (Закон циркуляции и преобразования энергии)</li><li>53-奇特生命识别标准 (Стандарты идентификации необычных существ)</li></ul>',34)])])}const p=a(e,[["render",d]]);export{u as __pageData,p as default};
